/** Parameters settable once on the client (globals option): CLI/MCP fill
 * them from flags or environment; the SDK falls back per request. */
export const GLOBALS: { name: string; option: string; flag: string; envSuffix: string }[] = [

];

export function findOp(resource: string, method: string): OpSpec | undefined {
  return OPS.find((op) => op.command[0] === resource && (op.command[1] === method || op.commandAlias === method));
}

export function missingRequired(op: OpSpec, values: Record<string, unknown>): string[] {
  return op.params
    .filter((p) => p.required && values[p.name] === undefined)
    .map((p) => p.name);
}

/**
 * Assemble the SDK method's positional arguments from a flat map of values
 * keyed by wire name (plus an optional raw body for bodyStyle "data" or a
 * --data base object).
 */
export function buildArgs(
  op: OpSpec,
  values: Record<string, unknown>,
  dataBody?: unknown,
  select?: string,
): unknown[] {
  const args: unknown[] = [];
  for (const p of op.params) {
    if (p.kind === "path") args.push(String(values[p.name] ?? ""));
  }
  if (op.hasBody) {
    if (op.bodyStyle === "fields") {
      const body: Record<string, unknown> = {};
      let used = false;
      if (dataBody !== undefined && dataBody !== null && typeof dataBody === "object") {
        Object.assign(body, dataBody as Record<string, unknown>);
        used = true;
      }
      for (const p of op.params) {
        if (p.kind === "body" && values[p.name] !== undefined) {
          body[p.name] = values[p.name];
          used = true;
        }
      }
      args.push(used ? body : undefined);
    } else {
      args.push(dataBody !== undefined ? dataBody : values.body);
    }
  }
  if (op.select) {
    args.push(select);
  }
  if (op.hasParams) {
    const params: Record<string, unknown> = {};
    let used = false;
    for (const p of op.params) {
      if ((p.kind === "query" || p.kind === "header") && values[p.name] !== undefined) {
        params[p.ts] = values[p.name];
        used = true;
      }
    }
    args.push(used ? params : undefined);
  }
  return args;
}
